664→                r#"
665→extends:
666→  - url: {}
667→app_name: ProjectApp
668→"#,
669→                server.url("/base.yml")
670→            ),
671→        )
672→        .unwrap();
673→
674→        // Local override file overrides app_name
675→        fs::write(
676→            bivvy_dir.join("config.local.yml"),
677→            "app_name: LocalOverride\n",
678→        )
679→        .unwrap();
680→
681→        let resolver = resolver_for_mock(&server);
682→        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();
683→
684→        // The extends resolution happens on the merged config,
685→        // so local override takes effect before extends
686→        // But since extends is in config.yml and local overrides app_name,
687→        // the merged config will have app_name=LocalOverride + extends from config.yml
688→        assert_eq!(config.app_name, Some("LocalOverride".to_string()));
689→        // Base step should be present (extends still works)
690→        assert!(config.steps.contains_key("install"));
691→    }
692→
693→    #[test]
694→    fn config_without_extends_still_works() {
695→        let temp = TempDir::new().unwrap();
696→        let bivvy_dir = temp.path().join(".bivvy");
697→        fs::create_dir_all(&bivvy_dir).unwrap();
698→        fs::write(bivvy_dir.join("config.yml"), "app_name: NoExtends").unwrap();
699→
700→        // Using default resolver — won't make any HTTP calls
701→        let config = load_merged_config(temp.path()).unwrap();
702→        assert_eq!(config.app_name, Some("NoExtends".to_string()));
703→    }
704→}
