  1→//! Install method detection.
  2→//!
  3→//! Detects how bivvy was installed to determine the update mechanism.
  4→
  5→use std::env;
  6→use std::path::{Path, PathBuf};
  7→use std::process::Command;
  8→
  9→/// How bivvy was installed.
 10→#[derive(Debug, Clone, PartialEq, Eq)]
 11→pub enum InstallMethod {
 12→    /// Installed via cargo install
 13→    Cargo,
 14→    /// Installed via Homebrew
 15→    Homebrew,
 16→    /// Downloaded binary or built from source
 17→    Manual { path: PathBuf },
 18→    /// Could not determine install method
 19→    Unknown,
 20→}
 21→
 22→impl InstallMethod {
 23→    /// Get the update command for this install method.
 24→    pub fn update_command(&self) -> Option<String> {
