623→"#,
624→                server.url("/base.yml")
625→            ),
626→        )
627→        .unwrap();
628→
629→        let resolver = resolver_for_mock(&server);
630→        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();
631→
632→        // Local overrides base
