301→    #[test]
302→    fn is_newer_version_empty_string() {
303→        // Edge case: empty strings
304→        // When latest is empty, it has no components, so can't be newer
305→        assert!(!is_newer_version("", "0.1.0"));
306→        // When current is empty, latest has more components, so is "newer"
307→        assert!(is_newer_version("0.1.0", ""));
308→    }
309→
310→    #[test]
311→    fn is_newer_version_invalid_format() {
312→        // Edge case: non-numeric components are filtered out
313→        // "abc" parses to empty vec, so can't be newer than 0.1.0
314→        assert!(!is_newer_version("abc", "0.1.0"));
315→        // Current "abc" parses to empty, so 0.1.0 is newer (has more components)
316→        assert!(is_newer_version("0.1.0", "abc"));
317→    }
