  1→//! Feedback command implementation.
  2→//!
  3→//! Captures and manages friction points during dogfooding, with automatic
  4→//! session correlation and optional external delivery via GitHub issues
  5→//! or email.
  6→
  7→use anyhow::Result;
  8→use clap::{Args, Subcommand};
  9→
 10→use crate::feedback::delivery::{
 11→    self, build_github_url, build_mailto_url, build_preview, build_title, DeliveryMethod,
 12→};
 13→use crate::feedback::{default_store_path, FeedbackEntry, FeedbackStatus, FeedbackStore};
 14→use crate::session::{default_store_path as session_store_path, Session, SessionId, SessionStore};
 15→use crate::ui::{Prompt, PromptOption, PromptResult, PromptType, UserInterface};
 16→
 17→use super::dispatcher::{Command, CommandResult};
 18→
 19→/// Known feedback categories that map to delivery routing.
 20→const KNOWN_CATEGORIES: &[&str] = &["bug", "feature", "ux", "other"];
 21→
 22→/// Arguments for the `feedback` command.
 23→#[derive(Debug, Clone, Args)]
 24→pub struct FeedbackArgs {
 25→    #[command(subcommand)]
 26→    pub command: Option<FeedbackSubcommand>,
 27→
 28→    /// Feedback message (when not using a subcommand).
 29→    #[arg(trailing_var_arg = true)]
 30→    pub message: Vec<String>,
 31→
 32→    /// Tags for categorization.
 33→    #[arg(short, long, value_delimiter = ',')]
 34→    pub tag: Vec<String>,
 35→
 36→    /// Session ID to attach (defaults to most recent).
 37→    #[arg(long)]
 38→    pub session: Option<String>,
 39→
 40→    /// Skip the delivery prompt (save locally only).
 41→    #[arg(long)]
 42→    pub no_deliver: bool,
 43→}
 44→
 45→/// Feedback subcommands.
 46→#[derive(Debug, Clone, Subcommand)]
 47→pub enum FeedbackSubcommand {
 48→    /// List feedback entries.
 49→    List {
 50→        /// Filter by status (open, resolved, wontfix).
 51→        #[arg(long)]
 52→        status: Option<String>,
 53→        /// Filter by tag.
 54→        #[arg(long)]
 55→        tag: Option<String>,
 56→        /// Show all (including resolved).
 57→        #[arg(long)]
 58→        all: bool,
 59→    },
 60→    /// Resolve a feedback entry.
 61→    Resolve {
 62→        /// Feedback ID.
 63→        id: String,
 64→        /// Resolution note.
 65→        #[arg(short, long)]
 66→        note: Option<String>,
 67→    },
 68→    /// Show feedback for a session.
 69→    Session {
 70→        /// Session ID (defaults to most recent).
 71→        id: Option<String>,
 72→    },
 73→}
 74→
 75→/// The feedback command implementation.
 76→pub struct FeedbackCommand {
 77→    args: FeedbackArgs,
 78→}
 79→
 80→impl FeedbackCommand {
 81→    /// Create a new feedback command.
 82→    pub fn new(args: FeedbackArgs) -> Self {
 83→        Self { args }
 84→    }
 85→}
 86→
 87→impl Command for FeedbackCommand {
 88→    fn execute(&self, ui: &mut dyn UserInterface) -> crate::error::Result<CommandResult> {
 89→        let store = FeedbackStore::new(default_store_path());
 90→
 91→        let exit_code = match &self.args.command {
 92→            Some(FeedbackSubcommand::List { status, tag, all }) => {
 93→                list_feedback(&store, status.clone(), tag.clone(), *all, ui)?
 94→            }
 95→            Some(FeedbackSubcommand::Resolve { id, note }) => {
 96→                resolve_feedback(&store, id, note.clone(), ui)?
 97→            }
 98→            Some(FeedbackSubcommand::Session { id }) => {
 99→                show_session_feedback(&store, id.clone(), ui)?
100→            }
101→            None => {
102→                if self.args.message.is_empty() {
103→                    capture_interactive(&store, self.args.tag.clone(), self.args.no_deliver, ui)?
104→                } else {
105→                    let message = self.args.message.join(" ");
106→                    let category = category_from_tags(&self.args.tag);
107→                    capture_feedback(
108→                        &store,
109→                        &message,
110→                        &category,
111→                        self.args.tag.clone(),
112→                        self.args.session.clone(),
113→                        self.args.no_deliver,
114→                        ui,
115→                    )?
116→                }
117→            }
118→        };
119→
120→        Ok(if exit_code == 0 {
121→            CommandResult::success()
122→        } else {
123→            CommandResult::failure(exit_code)
124→        })
125→    }
126→}
127→
128→/// Extract a delivery category from the tag list.
129→///
130→/// Uses the first tag that matches a known category. Falls back to "other".
131→fn category_from_tags(tags: &[String]) -> String {
132→    tags.iter()
133→        .find(|t| KNOWN_CATEGORIES.contains(&t.as_str()))
134→        .cloned()
135→        .unwrap_or_else(|| "other".to_string())
136→}
137→
138→fn capture_feedback(
139→    store: &FeedbackStore,
140→    message: &str,
141→    category: &str,
142→    tags: Vec<String>,
143→    session_id: Option<String>,
144→    no_deliver: bool,
145→    ui: &mut dyn UserInterface,
146→) -> Result<i32> {
147→    let session_store = SessionStore::new(session_store_path());
148→
149→    // Get session ID (provided, or most recent)
150→    let session = if let Some(id_str) = session_id {
151→        SessionId::parse(&id_str)
152→    } else {
153→        session_store.get_latest()?.map(|s| s.id)
154→    };
155→
156→    let mut entry = FeedbackEntry::new(message);
157→    if !tags.is_empty() {
158→        entry = entry.with_tags(tags);
159→    }
160→    if let Some(sid) = session.clone() {
161→        entry = entry.with_session(sid.clone());
162→    }
163→
164→    store.append(&entry)?;
165→
166→    let session_note = session
167→        .as_ref()
168→        .map(|s| format!(" (session {})", s))
169→        .unwrap_or_default();
170→
171→    ui.success(&format!("Feedback captured{}", session_note));
172→
173→    // Offer external delivery if interactive and not suppressed
174→    if !no_deliver && ui.is_interactive() {
175→        let full_session = session.and_then(|sid| session_store.load(&sid).ok());
176→        offer_delivery(store, &entry, category, full_session.as_ref(), ui)?;
177→    }
178→
179→    Ok(0)
180→}
181→
182→fn capture_interactive(
183→    store: &FeedbackStore,
184→    tags: Vec<String>,
185→    no_deliver: bool,
186→    ui: &mut dyn UserInterface,
187→) -> Result<i32> {
188→    if !ui.is_interactive() {
189→        ui.error("Interactive mode not available. Provide feedback as argument.");
190→        return Ok(1);
191→    }
192→
193→    // Ask for category first
194→    let category_prompt = Prompt {
195→        key: "feedback_category".to_string(),
196→        question: "What kind of feedback?".to_string(),
197→        prompt_type: PromptType::Select {
198→            options: vec![
199→                PromptOption {
200→                    label: "Bug - something broke".to_string(),
201→                    value: "bug".to_string(),
202→                },
203→                PromptOption {
204→                    label: "UX - confusing or awkward".to_string(),
205→                    value: "ux".to_string(),
206→                },
207→                PromptOption {
208→                    label: "Feature - missing or incomplete".to_string(),
209→                    value: "feature".to_string(),
210→                },
211→                PromptOption {
212→                    label: "Other".to_string(),
213→                    value: "other".to_string(),
214→                },
215→            ],
216→        },
217→        default: None,
218→    };
219→
220→    let category = match ui.prompt(&category_prompt)? {
221→        PromptResult::String(s) => s,
222→        _ => "other".to_string(),
223→    };
224→
225→    let prompt = Prompt {
226→        key: "feedback_message".to_string(),
227→        question: "Describe your feedback:".to_string(),
228→        prompt_type: PromptType::Input,
229→        default: None,
230→    };
231→
232→    let result = ui.prompt(&prompt)?;
233→    let message = match result {
234→        PromptResult::String(s) => s,
235→        _ => String::new(),
236→    };
237→
238→    if message.is_empty() {
239→        ui.warning("No feedback provided");
240→        return Ok(1);
241→    }
242→
243→    // Merge category into tags
244→    let mut all_tags = tags;
245→    if !category.is_empty() && category != "other" {
246→        all_tags.insert(0, category.clone());
247→    }
248→
249→    let all_tags = if all_tags.is_empty() {
250→        let tag_prompt = Prompt {
251→            key: "feedback_tags".to_string(),
252→            question: "Tags (optional, comma-separated):".to_string(),
253→            prompt_type: PromptType::Input,
254→            default: None,
255→        };
256→
257→        match ui.prompt(&tag_prompt)? {
258→            PromptResult::String(s) if !s.is_empty() => {
259→                s.split(',').map(|s| s.trim().to_string()).collect()
260→            }
261→            _ => vec![],
262→        }
263→    } else {
264→        all_tags
265→    };
266→
267→    capture_feedback(store, &message, &category, all_tags, None, no_deliver, ui)
268→}
269→
270→/// Offer to deliver feedback externally via GitHub issue or email.
271→fn offer_delivery(
272→    store: &FeedbackStore,
273→    entry: &FeedbackEntry,
274→    category: &str,
275→    session: Option<&Session>,
276→    ui: &mut dyn UserInterface,
277→) -> Result<()> {
278→    let method = delivery::determine_method(category);
279→
280→    // Show preview
281→    let preview = build_preview(entry, category, session, &method);
282→    ui.message(&preview);
283→
284→    // Prompt for confirmation
285→    let confirm_prompt = Prompt {
286→        key: "feedback_deliver".to_string(),
287→        question: "Send feedback?".to_string(),
288→        prompt_type: PromptType::Select {
289→            options: vec![
290→                PromptOption {
291→                    label: "Open in browser".to_string(),
292→                    value: "yes".to_string(),
293→                },
294→                PromptOption {
295→                    label: "Skip".to_string(),
296→                    value: "no".to_string(),
297→                },
298→            ],
299→        },
300→        default: None,
301→    };
302→
303→    let response = ui.prompt(&confirm_prompt)?;
304→    let choice = match response {
305→        PromptResult::String(s) => s,
306→        _ => "no".to_string(),
307→    };
308→
309→    if choice == "yes" {
310→        let url = match &method {
311→            DeliveryMethod::GitHubIssue { labels } => {
312→                let title = build_title(entry, category);
313→                let body = delivery::scrub_payload(&delivery::build_github_body(entry, session));
314→                build_github_url(&title, &body, labels)
315→            }
316→            DeliveryMethod::Email { to } => {
317→                let subject = delivery::build_email_subject(entry, category);
318→                let body = delivery::scrub_payload(&delivery::build_email_body(entry, session));
319→                build_mailto_url(to, &subject, &body)
320→            }
321→        };
322→
323→        match delivery::open_url(&url) {
324→            Ok(()) => {
325→                ui.success("Opened in browser. Complete submission there.");
326→                // Mark as delivered
327→                let _ = store.update(&entry.id, |e| {
328→                    e.delivered = Some(true);
329→                });
330→            }
331→            Err(e) => {
332→                ui.warning(&format!("Could not open browser: {}", e));
333→                ui.message(&format!("You can open this URL manually:\n  {}", url));
334→            }
335→        }
336→    } else {
337→        ui.message("Feedback saved locally.");
338→    }
339→
340→    Ok(())
341→}
342→
343→fn list_feedback(
344→    store: &FeedbackStore,
345→    status: Option<String>,
346→    tag: Option<String>,
347→    all: bool,
348→    ui: &mut dyn UserInterface,
349→) -> Result<i32> {
350→    let entries = if let Some(status_str) = status {
351→        let status = match status_str.as_str() {
352→            "open" => FeedbackStatus::Open,
353→            "resolved" => FeedbackStatus::Resolved,
354→            "wontfix" => FeedbackStatus::WontFix,
355→            "inprogress" | "in_progress" => FeedbackStatus::InProgress,
356→            _ => {
357→                ui.error(&format!("Unknown status: {}", status_str));
358→                return Ok(1);
359→            }
360→        };
361→        store.list_by_status(status)?
362→    } else if let Some(tag) = tag {
363→        store.list_by_tag(&tag)?
364→    } else if all {
365→        store.list_all()?
366→    } else {
367→        // Default: show open only
368→        store.list_by_status(FeedbackStatus::Open)?
369→    };
370→
371→    if entries.is_empty() {
372→        ui.message("No feedback entries found");
373→        return Ok(0);
374→    }
375→
376→    ui.message(&format!("{} feedback entries:\n", entries.len()));
377→    for entry in entries {
378→        let status_icon = match entry.status {
379→            FeedbackStatus::Open => "[ ]",
380→            FeedbackStatus::InProgress => "[~]",
381→            FeedbackStatus::Resolved => "[x]",
382→            FeedbackStatus::WontFix => "[-]",
383→        };
384→        let tags = if entry.tags.is_empty() {
385→            String::new()
386→        } else {
387→            format!(" [{}]", entry.tags.join(", "))
388→        };
389→        let session = entry
390→            .session_id
391→            .map(|s| format!(" ({})", s))
392→            .unwrap_or_default();
393→
394→        ui.message(&format!(
395→            "{} {} {}{}{}",
396→            status_icon, entry.id, entry.message, tags, session
397→        ));
398→    }
399→
400→    Ok(0)
401→}
402→
403→fn resolve_feedback(
404→    store: &FeedbackStore,
405→    id: &str,
406→    note: Option<String>,
407→    ui: &mut dyn UserInterface,
408→) -> Result<i32> {
409→    let resolution = note.unwrap_or_else(|| "Resolved".to_string());
410→
411→    let found = store.update(id, |entry| {
412→        entry.resolve(&resolution);
413→    })?;
414→
415→    if found {
416→        ui.success(&format!("Resolved {}", id));
417→        Ok(0)
418→    } else {
419→        ui.error(&format!("Feedback {} not found", id));
420→        Ok(1)
421→    }
422→}
423→
424→fn show_session_feedback(
425→    store: &FeedbackStore,
426→    session_id: Option<String>,
427→    ui: &mut dyn UserInterface,
428→) -> Result<i32> {
429→    let session_store = SessionStore::new(session_store_path());
430→
431→    let session = if let Some(id_str) = session_id {
432→        SessionId::parse(&id_str)
433→    } else {
434→        session_store.get_latest()?.map(|s| s.id)
435→    };
436→
437→    let Some(sid) = session else {
438→        ui.message("No sessions found");
439→        return Ok(0);
440→    };
441→
442→    let entries = store.list_by_session(&sid)?;
443→    if entries.is_empty() {
444→        ui.message(&format!("No feedback for session {}", sid));
445→        return Ok(0);
446→    }
447→
448→    ui.message(&format!("Feedback for session {}:\n", sid));
449→    for entry in entries {
450→        ui.message(&format!("  {} {}", entry.id, entry.message));
451→    }
452→
453→    Ok(0)
454→}
