  1→//! Persistent state storage.
  2→//!
  3→//! This module provides the main state storage for Bivvy projects,
  4→//! including step states and run history.
  5→
  6→use chrono::{DateTime, Utc};
  7→use serde::{Deserialize, Serialize};
  8→use std::collections::HashMap;
  9→use std::fs;
 10→use std::path::PathBuf;
 11→
 12→use super::{ProjectId, RunRecord};
 13→
 14→/// Persistent state for a project.
 15→#[derive(Debug, Clone, Serialize, Deserialize)]
 16→pub struct StateStore {
 17→    /// Schema version for migration.
 18→    pub version: u32,
 19→
 20→    /// Project identification.
 21→    pub project: ProjectInfo,
 22→
 23→    /// Last run timestamp.
 24→    pub last_run: Option<DateTime<Utc>>,
 25→
 26→    /// Last workflow executed.
 27→    pub last_workflow: Option<String>,
 28→
 29→    /// State for each step.
 30→    pub steps: HashMap<String, StepState>,
 31→
 32→    /// Run history (most recent first).
 33→    #[serde(default)]
 34→    pub runs: Vec<RunRecord>,
 35→}
 36→
 37→/// Project information stored in state.
 38→#[derive(Debug, Clone, Serialize, Deserialize)]
 39→pub struct ProjectInfo {
 40→    pub path: String,
 41→    pub git_remote: Option<String>,
 42→    pub name: String,
 43→}
 44→
 45→/// State for a single step.
 46→#[derive(Debug, Clone, Serialize, Deserialize)]
 47→pub struct StepState {
 48→    /// When this step last ran.
 49→    pub last_run: Option<DateTime<Utc>>,
 50→
 51→    /// Status of the last run.
 52→    pub status: StepStatus,
 53→
 54→    /// Duration of the last run in milliseconds.
 55→    pub duration_ms: Option<u64>,
 56→
 57→    /// Hash of watched files at last run.
 58→    pub watches_hash: Option<String>,
 59→}
 60→
 61→/// Status of a step execution.
 62→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 63→pub enum StepStatus {
 64→    Success,
 65→    Failed,
 66→    Skipped,
 67→    NeverRun,
 68→}
 69→
 70→/// Entry in step history.
 71→#[derive(Debug, Clone)]
 72→pub struct StepHistoryEntry {
 73→    pub timestamp: DateTime<Utc>,
 74→    pub status: StepStatus,
 75→    pub workflow: String,
 76→}
 77→
 78→/// Summary for status command.
 79→#[derive(Debug, Clone)]
 80→pub struct StatusSummary {
 81→    pub last_run: Option<DateTime<Utc>>,
 82→    pub last_workflow: Option<String>,
 83→    pub step_count: usize,
 84→    pub complete_count: usize,
 85→}
 86→
 87→/// Size information for state.
 88→#[derive(Debug, Clone)]
 89→pub struct StateSize {
 90→    pub run_count: usize,
 91→    pub step_count: usize,
 92→}
 93→
 94→impl StateStore {
 95→    /// Current schema version.
 96→    pub const CURRENT_VERSION: u32 = 1;
 97→
 98→    /// Default number of runs to keep.
 99→    pub const DEFAULT_HISTORY_RETENTION: usize = 50;
100→
101→    /// Create a new state store for a project.
102→    pub fn new(project_id: &ProjectId) -> Self {
103→        Self {
104→            version: Self::CURRENT_VERSION,
105→            project: ProjectInfo {
106→                path: project_id.path().to_string_lossy().to_string(),
107→                git_remote: project_id.git_remote().map(String::from),
108→                name: project_id.name().to_string(),
109→            },
110→            last_run: None,
111→            last_workflow: None,
112→            steps: HashMap::new(),
113→            runs: Vec::new(),
114→        }
115→    }
116→
117→    /// Get the state directory for a project.
118→    pub fn state_dir(project_id: &ProjectId) -> PathBuf {
119→        dirs::home_dir()
120→            .unwrap_or_else(|| PathBuf::from("~"))
121→            .join(".bivvy")
122→            .join("projects")
123→            .join(project_id.hash())
124→    }
125→
126→    /// Get the state file path.
127→    pub fn state_file(project_id: &ProjectId) -> PathBuf {
128→        Self::state_dir(project_id).join("state.yml")
129→    }
130→
131→    /// Load state from disk.
132→    pub fn load(project_id: &ProjectId) -> crate::error::Result<Self> {
133→        let path = Self::state_file(project_id);
134→
135→        if !path.exists() {
136→            return Ok(Self::new(project_id));
137→        }
138→
139→        let content = fs::read_to_string(&path)?;
140→        let state: Self = serde_yaml::from_str(&content).map_err(|e| {
141→            crate::error::BivvyError::ConfigParseError {
142→                path: path.clone(),
143→                message: e.to_string(),
144→            }
145→        })?;
146→
147→        Ok(state)
148→    }
149→
150→    /// Save state to disk using atomic write.
151→    ///
152→    /// Uses the write-to-temp-then-rename pattern to prevent corruption
153→    /// if the process crashes or loses power during the write operation.
154→    /// This ensures state files are never partially written.
155→    pub fn save(&self, project_id: &ProjectId) -> crate::error::Result<()> {
156→        let dir = Self::state_dir(project_id);
157→        fs::create_dir_all(&dir)?;
158→
159→        let path = Self::state_file(project_id);
160→        let content = serde_yaml::to_string(self).map_err(|e| {
161→            crate::error::BivvyError::ConfigValidationError {
162→                message: format!("Failed to serialize state: {}", e),
163→            }
164→        })?;
165→
166→        // Atomic write: write to temp file, then rename
167→        // This prevents corruption if process crashes mid-write
168→        let temp_path = path.with_extension("yml.tmp");
169→        fs::write(&temp_path, &content)?;
170→        fs::rename(&temp_path, &path)?;
171→
172→        Ok(())
173→    }
174→
175→    /// Get state for a step.
176→    pub fn get_step(&self, name: &str) -> Option<&StepState> {
177→        self.steps.get(name)
178→    }
179→
180→    /// Update state for a step.
181→    pub fn update_step(&mut self, name: &str, state: StepState) {
182→        self.steps.insert(name.to_string(), state);
183→    }
184→
185→    // --- Step State Tracking ---
186→
187→    /// Record a step execution result.
188→    pub fn record_step_result(
189→        &mut self,
190→        step: &str,
191→        status: StepStatus,
192→        duration: std::time::Duration,
193→        watches_hash: Option<String>,
194→    ) {
195→        let state = StepState {
196→            last_run: Some(Utc::now()),
197→            status,
198→            duration_ms: Some(duration.as_millis() as u64),
199→            watches_hash,
200→        };
201→        self.steps.insert(step.to_string(), state);
202→    }
203→
204→    /// Check if a step has been run successfully.
205→    pub fn is_step_complete(&self, step: &str) -> bool {
206→        self.steps
207→            .get(step)
208→            .map(|s| s.status == StepStatus::Success)
209→            .unwrap_or(false)
210→    }
211→
212→    /// Get the last run time for a step.
213→    pub fn step_last_run(&self, step: &str) -> Option<DateTime<Utc>> {
214→        self.steps.get(step).and_then(|s| s.last_run)
215→    }
216→
217→    /// Clear state for a specific step.
218→    pub fn clear_step(&mut self, step: &str) {
219→        self.steps.remove(step);
220→    }
221→
222→    /// Clear all step states.
223→    pub fn clear_all_steps(&mut self) {
224→        self.steps.clear();
225→    }
226→
227→    // --- Run History ---
228→
229→    /// Record a completed run.
230→    pub fn record_run(&mut self, record: RunRecord) {
231→        self.last_run = Some(record.timestamp);
232→        self.last_workflow = Some(record.workflow.clone());
233→        self.runs.insert(0, record);
234→    }
235→
236→    /// Get the most recent run.
237→    pub fn last_run_record(&self) -> Option<&RunRecord> {
238→        self.runs.first()
239→    }
240→
241→    /// Get run history (most recent first).
242→    pub fn run_history(&self, limit: usize) -> &[RunRecord] {
243→        let len = self.runs.len().min(limit);
244→        &self.runs[..len]
245→    }
246→
247→    // --- Query Methods ---
248→
249→    /// Get last run details for a specific step.
250→    pub fn step_history(&self, step: &str) -> Vec<StepHistoryEntry> {
251→        self.runs
252→            .iter()
253→            .filter_map(|run| {
254→                if run.steps_run.contains(&step.to_string()) {
255→                    Some(StepHistoryEntry {
256→                        timestamp: run.timestamp,
257→                        status: if run.status == super::RunStatus::Success {
258→                            StepStatus::Success
259→                        } else {
260→                            StepStatus::Failed
261→                        },
262→                        workflow: run.workflow.clone(),
263→                    })
264→                } else if run.steps_skipped.contains(&step.to_string()) {
265→                    Some(StepHistoryEntry {
266→                        timestamp: run.timestamp,
267→                        status: StepStatus::Skipped,
268→                        workflow: run.workflow.clone(),
269→                    })
270→                } else {
271→                    None
272→                }
273→            })
274→            .collect()
275→    }
276→
277→    /// Get a summary for the status command.
278→    pub fn status_summary(&self) -> StatusSummary {
279→        StatusSummary {
280→            last_run: self.last_run,
281→            last_workflow: self.last_workflow.clone(),
282→            step_count: self.steps.len(),
283→            complete_count: self
284→                .steps
285→                .values()
286→                .filter(|s| s.status == StepStatus::Success)
287→                .count(),
288→        }
289→    }
290→
291→    // --- History Pruning ---
292→
293→    /// Prune old run history.
294→    pub fn prune_history(&mut self, keep: usize) {
295→        if self.runs.len() > keep {
296→            self.runs.truncate(keep);
297→        }
298→    }
299→
300→    /// Clean up state (remove old data, prune history).
301→    pub fn cleanup(&mut self, retention: usize) {
302→        self.prune_history(retention);
303→
304→        // Remove step state for steps not in recent runs
305→        let recent_steps: std::collections::HashSet<String> = self
306→            .runs
307→            .iter()
308→            .flat_map(|r| r.steps_run.iter().chain(r.steps_skipped.iter()))
309→            .cloned()
310→            .collect();
311→
312→        self.steps.retain(|name, _| recent_steps.contains(name));
313→    }
314→
315→    /// Get the size of the state (for diagnostics).
316→    pub fn size(&self) -> StateSize {
317→        StateSize {
318→            run_count: self.runs.len(),
319→            step_count: self.steps.len(),
320→        }
321→    }
322→}
323→
324→impl Default for StepState {
325→    fn default() -> Self {
326→        Self {
327→            last_run: None,
328→            status: StepStatus::NeverRun,
329→            duration_ms: None,
330→            watches_hash: None,
331→        }
332→    }
333→}
