mod entry;
mod store;

pub use entry::{FeedbackEntry, FeedbackStatus};
pub use store::FeedbackStore;

/// Get the default feedback store path.
pub fn default_store_path() -> std::path::PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(|| std::path::PathBuf::from("."))
        .join("bivvy")
        .join("feedback.jsonl")
}

